#!/usr/bin/env python3
from pathlib import Path
import json,html
R=Path(__file__).resolve().parent.parent
c=json.loads((R/'verification/FEATURE_CATALOG.json').read_text());c['version']='0.7.14'
changes={
'F02':('统一外部读取器','战术、单位统计和光标统一使用 ReadSession。同一 PID 和访问能力共享受引用计数保护的只读连接，缓存、失败诊断和批次计数归各任务独立所有；仅连接登记加短锁，读取和整批采样不持全局锁。统计/战术使用批次页面缓存，光标使用 readFresh 即时读取。只查询连接与可读连接隔离，关闭一个模块不关闭其它模块的连接。进程退出后重新连接生成新代次并清空该会话缓存。','external_reader/source/process_connection.h; process_reader.h; shared_reader.h'),
'F04':('单运行库执行管理','ManageGameEntry、战术执行、光标采样与隐藏/恢复共同链接到 GameRuntime.dll。执行令牌在所有编译单元间共享唯一实例；普通进入不允许重入，原版同步捕获使用显式 Capture 和后进先出释放。不存在独立管理器 DLL 或功能私自加载桥接 DLL。','shared/source/game_entry_client.h; shared/source/game_entry_manager.cpp; game_runtime/source/runtime.cpp'),
'F06':('宿主统一连接与调度','host_game_input 为每个游戏维护一组 GETMESSAGE/POST Hook，功能持有不同订阅号。两个 UI 线程共用同一个管理对象；关闭一个订阅不卸掉另一订阅使用的 Hook。光标 WM_SETCURSOR 也经宿主输入管理器校验 PID/前台，等待窗口处理时不持调度锁。宿主按光标 4ms、战术 16ms 的目标间隔标记就绪并合并唤醒，丢失唤醒最多每 250ms 重新发送；这些是目标间隔，实际执行取决于系统调度及游戏取消息的时机。','shared/source/host_game_input.h; shared/source/runtime_protocol.h'),
'F07':('请求排队与游戏线程提交','宿主保存用户命令队列、选兵邮箱和外部规划结果；单 DLL 在游戏线程依次服务已就绪的光标和战术工作。选兵和规划仍是同一协议的逻辑邮箱，不安装独立 Hook。默认消息触发；实验帧模式只消费宿主授予的一次待处理标记，没有宿主标记就不运行普通任务。原版构造器和单机 DoList / 联机 OutList 路由不变。游戏侧保留原版队列、重试、去重、在途回执、对象合法性和即时鼠标捕获状态。','shared/source/host_game_input.h; game_runtime/source/runtime.cpp; assist/source/command_delivery.h; assist/source/bridge.cpp'),
'F15':('同类型与武器变体选兵','选兵使用统一 Shared 协议中的 selectRequest/selectAck 优先邮箱，避免等待玩法命令 ACK。它是同一 DLL 和消息入口内的逻辑优先通道，没有额外线程或 Hook。执行时仍校验对局、对象和游戏线程权限。','assist/source/type_select_bridge.h; assist/source/bridge.cpp; assist/source/main.cpp'),
'F55':('原光标隐藏模式','提供原光标、隐藏、透明 SHA 与无光标诊断。隐藏和恢复由 GameRuntime 的光标服务执行；与战术服务共享一份执行令牌。停止成功后释放游戏侧映射，下一次启用重新连接。100ms 游戏线程看门狗只处理停止/失活恢复，不执行正常待发任务。','cursor/source/hide.cpp; game_runtime/source/runtime.cpp'),
'F57':('游戏内光标刷新','在唯一 GameRuntime 中执行原生光标更新和 WM_SETCURSOR 后修复，处理菜单和焦点变化。采样与战术提交顺序执行；宿主统一唤醒，光标模块不再拥有独立游戏内轮询定时器。','cursor/source/hide.cpp; game_runtime/source/runtime.cpp'),
'F67':('现代化统一界面','保留 0.6.2.15 的统一侧栏、深色按钮和开关；战术设置为一张连续滚动页，三个标题，支持按名称定位。设置即时生效并自动保存，原快捷键和 INI 格式兼容。','shared/source/modern_ui.h; suite/source/main.cpp; assist/source/ui_layout.h')}
changes['F43']=('载员与剩余容量','按统一只读显示策略随菜单隐藏/恢复。可见载具同一逻辑帧内重读坐标与乘员链，并复核对象身份/类型/所有者及存活状态；插值采用外部采样帧，容量立即更新。前台目标跟随 5–500 Hz 配置，实际耗时见 Runtime.log，不承诺实测屏幕帧率。','external_reader/source/display_state.h; tactical_sampler.h; assist/source/label_motion.h; main.cpp')
changes['F27']=('满载返矿','外部 World 包含存矿量、容量与可停靠矿厂类型；外部规划器选择兼容矿厂，GameRuntime 重新验证后经统一构造进入单机 DoList / 联机 OutList。0.7.10 将控制帧更新从显示扫描移回调度器，并保证规划/控制发布顺序；不会再因外部显示使控制帧停在零而全部拒绝。150ms/6帧、手动让权与对象版本限制保留。','assist/source/external_planner.h; external_orders_bridge.h; main.cpp; bridge.cpp')
changes['F39']=('科技全开（原生侧栏）','调用原生 AddCameo，侧栏点击/刷新两处调用点由统一管理器持令牌安装；对本玩家清单类型使用原版仅检查建造上限的查询，仍需匹配工厂。每批最多补8项，每栏最多75项，不重复添加。全局 CanBuild、Prerequisite/Owner、仿真事件处理不改。关闭/排除恢复原版资格，由后续原版刷新清理；工厂丢失走原版清理。单机 DirectProduce=0 不影响侧栏；联机沿用实验科技许可保护。模型未覆盖完整生产经济/真实联网。','assist/source/sidebar.h; hook_registry.h; guard.cpp; bridge.cpp 的 OpenTech')
changes['F27']=('满载返矿与到场优先','满载己方矿车由外部 Planner 选择兼容矿场并排队。2格内已到场车可优先于4格外预约车：经统一 OreYield 原生 Move 让位，观察原版 Move 和预约释放后再 Enter。每矿场一轮一车、每载货任务最多被插一次，被插车保留下一轮优先。最多3次让位重试，未释放180帧退出；本轮360帧上限。不打断到场/卸货或手动接管，安全格不足时保留原排队。Runtime 复核原版状态后统一入单机 DoList / 联机 OutList，不直接写 radio。150ms/6帧及对局/手动版本检查保留。','assist/source/external_planner.h; ore_queue.h; external_orders_bridge.h; main.cpp')
for f in c['features']:
 if f['id'] in changes:f['name'],f['implementation'],f['source']=changes[f['id']]
 if f['id']=='F39':f['gateway_route']='OpenTech -> GameRuntime -> managed sidebar calls / native input; external Produce -> unified event gateway'
 if f['id'] in ('F01','F02','F03'):
  f['gateway_route']='ReadSession -> shared process connection / task-local cache / layout probe'
  f['review_13']='读取与命令就绪独立；0.7.1 已替换旧版共享批次缓存及整批读锁。'
 # Existing behavior fixes carried forward from the UI release.
 if f.get('review_15') and f['id'] not in changes:f['implementation']+=' '+f['review_15']
c['scope_07']='Single injected project DLL; external scheduler and retained game-side execution state. Actual Windows UI/game/network not tested.'
(R/'FEATURE_CATALOG.json').write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n')
e=html.escape
features=''.join(f'<article id="{f["id"]}"><h3>{f["id"]} · {e(f["name"])}</h3><p>{e(f["implementation"])}</p><p class="source">实现：{e(f["source"])}</p></article>' for f in c['features'])
body='''<h1>RA2 Toolbox 0.7.14 Full</h1><p class="lead">单游戏运行库 · 外部调度 · 完整离线资源</p>
<h2>安装与升级</h2><p>退出旧工具箱和游戏，完整解压到新目录，运行 Start-Message.cmd。无需再下载旧 Full 包或编译。要保留设置，可在退出后复制旧版的 INI 到新目录；不要复制旧 EXE/DLL。已加载的 0.6.x DLL 会被游戏保持引用，必须重启游戏；发现旧桥接或旧管理器已注入时，新运行库拒绝连接。</p>
<p>项目运行文件为 RA2Toolbox.exe 和 GameRuntime.dll，均为 Windows x86。runtime/ 内的 Python 与 NumPy/SciPy/OpenCV 是独立 x64 离线预处理程序的依赖，不注入游戏。适用 Windows 10/11 x64。原有 assets、三套 profiles、engine、runtime 和许可证均包含；仅去掉原包两个零字节 wheel 下载占位文件。</p>
<h2>整体架构</h2><table><tr><th>层</th><th>职责与边界</th></tr>
<tr><td>主程序</td><td>UI、自动保存、统一只读采样、用户请求排队、选兵邮箱、协作等已外置规划；host_game_input 统一持有订阅、Hook 对和唤醒节拍。</td></tr>
<tr><td>单游戏运行库</td><td>GameRuntime.dll 包含消息分发、光标服务、战术执行和 ManageGameEntry。每次消息先取得正确游戏线程身份，再依次服务就绪模块。所有普通执行均先释放上一份权限；同步输入捕获用受控嵌套令牌。</td></tr>
<tr><td>原版游戏接口</td><td>统一构造、单/联机队列选择、有效性与版本检查。原版事件队列、待确认执行记录和短期回退状态留在游戏侧；UI 不伪造 ACK，接收仿真事件不经过本地输入转换。</td></tr>
<tr><td>读取和覆盖层</td><td>单位统计继续外部只读，删除未使用的 UnitMonitorBridge 注入产物。覆盖层各自绘制，读取不申请下令执行令牌；仍受 CPU、系统调度和游戏状态影响。</td></tr></table>
<p>一个进程仍可能需要不同类型的 Hook：GETMESSAGE 接收任务、POST 在 WM_SETCURSOR 之后修复光标、已登记的原版输入/帧 detour 处理同步游戏边界。它们全部属于同一个 GameRuntime，并受同一个管理器约束；“一个 DLL”不意味着只有一个回调，也不意味着允许并发调用非线程安全游戏函数。</p>
<p>原光标独立的游戏内 10ms 工作定时器已移除。游戏内仅保留 100ms 故障恢复看门狗，宿主崩溃或停止后尽量恢复光标/补丁；看门狗不执行活跃宿主的普通待发命令。游戏线程完全卡死时不能保证即时恢复。</p>
<h2>继承 0.7.3：外部规划时效约束</h2>
<p>本轮为既有外部规划通道增加时效保障，没有把剩余业务算法全部迁出 Runtime。规划请求协议为 34，必须使用同版 EXE 和 DLL并重启游戏升级。</p>
<table><tr><th>通道</th><th>源数据有效上限</th><th>过期处理</th></tr><tr><td>高级移动、磁电、矿车规划</td><td>150ms 且不超过 6 帧</td><td>未发送项作废，等待新快照重新规划。不会把过期误记为目标非法或移动失败。</td></tr><tr><td>高级进驻、飞机分配</td><td>250ms 且不超过 12 帧</td><td>保留已处理前缀，只重新读取并分配未处理后缀；飞机保留已提交目标计数。</td></tr></table>
<p>时间戳取自采样起点，不能在计算完成或重新排队时刷新。计算前后检查时效，Runtime 在每条提交前同时检查对局、帧数、时间和当前原版合法性。部分批次也不能获得额外数秒的旧数据发送窗口。</p>
<p>协同读取前后通过统一读取器的 readFresh 核对游戏帧号和己方阵营；帧倒退、阵营改变或超预算则重试；允许有效预算内跨帧读取，不因大选区无法一帧读完而直接拒绝。页面缓存不参与这些边界检查。点击意图最多保留 5 秒，期间每次重试必须取得新快照；这不是旧快照可用 5 秒。已发送事件通过原版事件系统执行，不撤回或私改网络包。</p>
<p>上述数字是提交前拒绝过期结果的上限，不是响应速度承诺，也不包含原版事件提交后的网络传输与执行时延。尚未测量真实游戏端到端 P95/P99；极大选区若连续计算超预算，可能反复重试并最终超时。边界检查也不等于原子世界快照，因此最终游戏侧合法性检查不能删除。</p>
<h2>追加现场反馈：观战整机卡顿与部分功能掉线</h2><p>用户报告观战时整个系统严重卡顿，关闭工具箱恢复；自动装车、智能进驻、自动维修、自动倒矿暂未掉线，磁电轮换攻击、飞机高级攻击、飞碟主武器、变卖战车和自动CS会掉线。这是现场负面证据，不能用既有双端模型通过覆盖，也不能将“尚未掉线”写成所有场景安全。</p><p>本次确认并修正两处额外开销：有持续新回执的观战/菜单连接不会再因没有可操作对局身份而每8秒重建；同一逻辑帧持续移动相机时，可见对象的位置/载员仍按显示频率更新，但全场候选枚举最多约每16ms一次。离开视口不再误触发每次采样的全场重扫；提示线和箱子跟随相机平移。1000次2ms采样测试最多126次全场枚举。新逻辑帧、选择、配置或对象失效仍立即更新；显示目标5–500Hz未改变。以上是代码确认的开销修正，尚未在用户电脑证明能消除整机卡顿。</p><table><tr><th>功能</th><th>实现差异</th></tr><tr><td>装车/智能进驻/倒矿</td><td>Enter/Move；运输容量、原版进入合法性或矿场预约。进驻也有鼠标Hook，因此不能把掉线统归于Hook。</td></tr><tr><td>自动CS</td><td>统一Runtime管理器许可的本地输入捕获，把Move=2改为AttackMove=29，再续接原版构造和外发；不直接写任务内存，也不经过宿主普通request/ack邮箱。</td></tr><tr><td>自动维修</td><td>Repair对象事件。</td></tr><tr><td>磁电轮换</td><td>持续攻击目标规划、原始武器/冷却/抬升字段读取，再提交Attack；没有调用SelectWeapon之类游戏决策函数。</td></tr><tr><td>飞机高级攻击</td><td>捕获点击，外部分配目标，武器兼容复核，然后Attack。</td></tr><tr><td>飞碟主武器</td><td>Ctrl点击建筑转换为攻击其地面格，目标tag=11；与普通攻击对象tag=0x34不同。</td></tr><tr><td>变卖战车</td><td>接管变卖光标与鼠标抬起；Ctrl放宽本地判定，要求车所在格有建筑，再发Sell对象事件0x16。与维修共用对象事件入口，但接收语义不同。</td></tr></table><p>上述任务最终都走统一入口。单一入口只解决仲裁、线程和入队，不证明原版接收端、MOD钩子及完整仿真无副作用。已经取得并审阅工具箱Runtime.log，仍缺游戏同步错误/崩溃记录及游戏版本，尚未确定掉线根因；本版没有宣称修复这五项真实联机故障，也未以静默禁用功能掩盖故障。</p><p>已审阅用户追加的0.7.10日志：750行、355条桥健康记录、12次游戏进程连接，未记录桥内SEH异常。最后一局的控制帧停在168，但桥回调继续增加，随后记录有模态窗口；这不能区分暂停、同步错误或连接中断。读取耗时记录仅覆盖显示采样，不能据此排除整机卡顿。详见 verification/NETPLAY_LOG_REVIEW.json。本版默认健康日志补充CS转换次数、输入Hook/冲突、队列拒绝和阶段耗时，持续订单变化最多每500ms记录一次，文件写入仍在宿主。</p><p>新增LAN/Internet两种会话的单边CS用例：仅一端安装Hook，该端真实原版函数发出AttackMove=29，另一端发出Move=2；两端都接收相同合并事件流。测试仍未执行原版接收器和完整游戏仿真，不是掉线修复证明。还需掉线时具体提示、游戏同步错误文件（如SYNC*.TXT）或崩溃记录，以及游戏/MOD/启动器版本。</p><h2>0.7.14：撤回 0.7.12 引擎診斷注入</h2><p>使用者對照回報：僅使用自動裝車與自動倒礦，0.7.11 不掉線，0.7.12 掉線。0.7.12 新增預設啟用的 CRC 錯誤入口 0x64CC61 與過期事件入口 0x64C5AF，安裝動作在功能判定與取樣節流之前；因此即使沒有開啟輸入轉換功能，也會嘗試安裝。現場 Runtime(1).log 明確記錄 crc=-1、late=1。此前把診斷用途當成不影響遊戲的假設不成立。</p><p>本版從 0.7.11 完整還原 Runtime 生產原始碼、協定、登記表及事件提交路徑，撤掉上述診斷 Hook、引擎事件追蹤環與額外捕獲邊界。停止先前未發布的 CRC 比較前 Hook 方案；0x64C6E9 不在本版的注入清單。外部自動 Runtime.log、既有異常與橋接健康記錄照舊。未改使用者功能開關，未停用自動裝車、倒礦或其他功能。</p><p>機器驗證：所有 Runtime 編譯依賴原始碼與 0.7.11 相同；新 DLL 的 .text、.rdata、.data、.eh_fram、.tls、.reloc 等非版本資源/建置識別區逐位元組相同。新增回歸以使用者提供的 EXE 和參考 EXE 驗證：0.7.12 在僅倒礦模式仍會修改過期事件入口；0.7.14 在單機/LAN/Internet 的開局、裝車發令、觀戰與停止重連案例中沒有寫入遊戲程式碼區。原版事件佇列發令仍有效。</p><p>實際 EXE 的 SHA256 是 268a81b7422b3bb855e1b4a162aadba4d807f88fb9f70feb99118211d8fbb8d0；0x64C6F2 原有六個位元組為 NOP，原同步錯誤分支不會由此比較跳入。此差異可解釋舊取證未安裝和該路徑沒有 SYNC 日誌，不證明平台掉線原因。本版不修改這些位元組。spawner.xdp 與 spawner2.xdp 是遊戲規則文字，不是動態函式庫；所有上傳遊戲檔案均未納入工具包。</p><p>這是針對新回歸的還原版本。已確認新增注入被撤回，未在真實平台確認掉線完全消失，也不宣稱解決 0.7.11 原先的自動 CS、磁電、飛機、飛碟、賣車等問題。測試使用真正 DLL 與 EXE 指令、合成 Win32/物件，不是完整雙人聯機。</p><p>升級時必須完全退出遊戲與工具，再解壓到新目錄；可沿用 INI，勿混用 EXE/DLL。Assist 協定回到 34，Runtime/Entry 仍為 3。已載入的 0.7.12 GameRuntime.dll 不能靠只換磁碟檔案卸載。</p><h2>繼承 0.7.11：矿场到场优先与防反复插队</h2><p>已在卸矿点附近等待的矿车，可以让仍在远处赶来的预约车让位。附近定义为距原版卸矿点不超过 2 格（棋盘距离）；被让位车必须超过 4 格，形成回滞区。按首次观察到达的帧号选择等待车，同帧按既有 FIFO 顺序；不按每帧距离反复改选。</p><p>外部 Planner 为每个矿场保留一份本轮服务状态。先通过现有 plan 邮箱发出 OreYield 原生 Move；收到入队 ACK 还不放行，必须再观察原预约消失、旧车的原版 Move 生效，才提交选中车的 Enter。同一矿场同时只选一辆插队车；不同矿场独立调度。让位和 Enter 都经过 GameRuntime、统一 nativeMission 入口、原版构造器及单机 DoList / 联机 OutList。本次无新 Hook、注入 DLL、直接 radio 写入或私有消息通道。</p><p>本轮选中的车不可再次被插队；被插队车保留下一轮优先权，同一载货任务最多被插一次，防止不断被新到车辆挤走。让位最多尝试 3 次、间隔至少 30 逻辑帧；未观察到释放则 180 帧后退出本轮，已放行但未完成的本轮状态最多 360 帧。超时保留原版正在卸货/停靠的保护，不通过直接改内存强行腾空矿场。成功入队不能当作卸货完成，收入判定仍需观察卸货和载量清空。</p><p>Runtime 提交前重新核对己方身份、手动版本、载矿量、开关、矿场兼容、原版占用、距离和安全等待格。已到场、正在卸矿、他车占用、玩家手动接管或没有可用等待格时不强行让位。矿车销毁/换主、矿场失效、手动版本改变、关功能或换局会清理本轮状态。150ms/6帧时效限制保留。关闭后按既有原生返矿流程释放待处理车。</p><p>新增 23 个外部按帧逻辑场景（含 ASan/UBSan）及 28 个真实 DLL 模型场景，覆盖同时到场、被插车优先、无进展、丢失/拒绝回执、双矿场、手动接管、消失对象与单/联机队列；完整既有回归重跑。模型显式模拟移动、radio 释放和卸货，不能证明各 MOD 实机一定会按预期释放原生预约。原版不释放时有界退出，不无限抢占。默认规划日志新增 oreBypasses、yieldAttempts、turnTimeouts。Assist 协议升级为 34，Runtime 3 / Entry 3 不变。</p><h2>继承 0.7.10：恢复原生科技侧栏，修复外部规划控制帧</h2><p>0.7.9 的外部显示模式跳过游戏侧 scan()，但控制快照的 frame 只在那里更新。新鲜矿车规划因此与停在 0 或菜单时刻的控制帧比较，被当作未来帧丢弃。旧 DLL 已复现：World=150、Snapshot=0，宿主不产生指令。现在每次有效调度更新控制帧，规划数据与对应控制状态发布后才通知宿主；竞争窗口内暂时领先的 World 保留待重试。150ms/6帧和跨局检查没有放宽。</p><p>科技不再仅统计外部目录。GameRuntime 调用 YRpp SidebarClass::AddCameo；通过统一补丁管理器登记侧栏点击与刷新两处 CanBuild 调用点，仅对本玩家配置类型请求原版“仅检查建造上限”路径。仍查询匹配工厂、保留原版生产/取消与工厂丢失处理。不修改全局 CanBuild、Prerequisite、Owner 或收到的仿真事件。每轮最多补 8 项，不重复添加已有图标；单栏上限 75。关闭/排除后恢复原版资格，由原版后续侧栏检查清理项目。外部列表 DirectProduce=0 不影响原生侧栏。</p><p>联机沿用实验科技许可保护：原生侧栏和外部直接生产共用同一许可，默认拒绝未验证的联机科技操作并明确返回 -13，避免新增侧栏绕开原有保护。单机无需此许可。许可不代表完整游戏生产、经济或联机同步已验收。</p><p>新增 23 项实际 DLL 模型测试：外部显示倒矿完整提交链路、无效候选/时效拒绝、侧栏添加/重复刷新/原版刷新分支/点击 ABI、配置排除、工厂变化、建造上限、槽位边界、错误线程、第三方补丁、全输入 Hook 共存/撤销及联机许可。原版 AddCameo/CanBuild/FindFactory 使用模型桩；事件构造器、DLL 与所测刷新分支运行真实机器码。85 项本地检查及原有 DLL 回归重跑。当前没有 Windows 游戏实机、生产经济或真实双人联机验收。</p><p>默认 Runtime.log 增加 controlFrame、techOpen/Visible/Unavailable/Error，以及 planner 的源帧/年龄、矿车总数/满载/手动暂停/任务、样本载量、矿厂数和计划回执。日志“入队”仍不冒充“已执行”。0.7.9 的计时 ABI、菜单隐藏、同帧载员刷新及高频显示修复保留。</p><h2>继承 0.7.5：控制台与显示修复</h2><p>统一 owner-draw 控件绘制，修正输入框对比度、静态文字背景擦除；显示采样跟随设置目标并独立使用 QPC，同帧重复采样不再压缩插值。统一管理器使用已验证 HWND 唤醒并保留失败阶段/错误码。现场已验证连接成功，后续执行异常诊断见本次修复。具体变更和验证边界见根目录 README.txt。</p><h2>继承 0.7.4：扩展测试与冲突修复</h2><p>新增组合测试复现并修复：协同同帧请求被显示采样周期阻塞、结束对局后协同回执未完成、两规划通道分别消耗额度导致维修饥饿。两个规划邮箱现在共用帧预算，均有待处理请求时先均分额度，仍使用统一原版事件入口。</p><p>10 项新增 DLL 冲突测试、240 次逻辑延迟请求、30000 组随机分配、100000 次预算调度、121 组功能优先级检查完成。14 个 CPU 工作负载提供 P50/P95/P99；不是实机端到端延迟。屏幕捕获工具已包含，Windows 捕获仍待实际电脑运行。详见 <a href="EXTENDED-TEST-REPORT.html">完整测试报告</a>。</p>
<h2>统一读取器（0.7.1 起）</h2><p>三个宿主模块统一使用 ReadSession。每个任务保留自己的页面缓存、诊断和批次计数，共享不可变连接和引用计数句柄；连接注册表仅在连接/复用时短暂加锁。统计扫描、战术扫描、协同目标读取和光标即时读取均不持全局采样锁。光标读取动态字段时使用 readFresh，不会命中上一批页面缓存；VM_READ 不可用时保留只查询连接和原有 Runtime 快照路径，不提升权限绕过平台。</p>
<p>并发验证在底层模拟 ReadProcessMemory 中设置屏障，确认三个调用同时进入；另验证其它模块连接/断开不阻塞这些读取、跨编译单元共享连接、缓存/诊断隔离、进程退出/PID 复用、只查询权限升级和最终句柄全部释放。原有 4000 批/256000 次读取测试继续通过。新增并发测试启用 AddressSanitizer 与 UndefinedBehaviorSanitizer；容器不能运行 LeakSanitizer，句柄生命周期通过显式计数断言验证。</p>
<p>统一读取器不等于全游戏原子快照：各业务仍各自采样并生成其快照，跨模块相同字段可能重复读取。战术显示采样跟随前台设置目标（5–500Hz），后台 250ms；同帧复用未变化场景；目标不等于测得吞吐，单位统计 250ms；光标按自身显示循环即时读取。未做实机吞吐测量，不承诺并行后固定倍数提速。换局身份、对象有效性检查仍由对应采样器保留，连接代次不冒充对局代次。</p>
<p>当前外置的是宿主请求队列、部分规划和唤醒。自动装车分配、repairTick/autoLoadTick/nativeOrdersTick 等仍位于 GameRuntime 内；本次仅迁移外部读取层，没有完成全部业务算法外置。游戏内合法性读取与同步 Hook 继续在 Runtime 的游戏线程执行。</p>
<h2>继承 0.7.2 的全量架构审视</h2><p>审计 119 个生产源文件，并递归追踪 77 个宿主依赖文件、64 个 Runtime 依赖文件（有公共头重叠）。核对外部读取、进程注入、原版函数调用、代码补丁、队列构造、回执写者、同步输入 Hook、帧提交和构建输出。结构检查与人工调用链复查不能证明所有运行时行为正确。</p>
<table><tr><th>发现</th><th>处置</th></tr><tr><td>光标模块直接 SendMessageTimeout(WM_SETCURSOR)</td><td>改走 host_game_input::refreshCursor，统一检查游戏 PID/前台，10ms 有界等待，不持宿主调度锁。</td></tr><tr><td>实验帧模式能独立运行普通任务</td><td>只有 Runtime 宿主消息入口能授予 hostWorkPending；消息/帧共同消费一次，帧只提供安全执行时点。拒绝进入或路由未选中时保留待处理标记。</td></tr><tr><td>同数字 PID 被复用后沿用旧控制器句柄</td><td>只有保留的进程句柄仍存活才复用连接；否则执行正常重连。测试以不同模拟进程句柄验证，而非只修改 PID。</td></tr><tr><td>Windows 重新编译可能保留旧成功标记</td><td>开始编译即清除旧标记和清单；Windows 构建成功必须重新通过 PE/版本/ABI 检查。Linux 构建也清理同名 verification 标记。</td></tr><tr><td>未来宿主可能误引入游戏执行头</td><td>宿主构建包含 game_entry_client.h 会报编译错误；新增递归依赖/API 归属检查，防止读取、输入、补丁和注入入口分叉。</td></tr></table>
<p>实际 DLL 新增验证：无宿主授权的帧回调不能处理待发命令；一次宿主授权只消费一次；宿主 PID 复用可重连。宿主测试验证光标刷新目标/前台拒绝、超时返回，以及等待游戏窗口时其它线程仍能取得调度锁。</p>
<p><strong>还未完全满足“全部业务规划外置”：</strong>自动装车候选收集与分配、自动维修扫描/周期逻辑、智能卸载/逃生后的目标选择仍在 Runtime。高级移动攻击/磁电决策已外置，不能把整个 nativeOrdersTick 都归为未迁移算法。后续应扩展统一候选快照/意图协议，迁出纯计算和周期策略，保留游戏内最终合法性校验和提交。</p>
<p>允许的边界：同步 CS/进驻等输入捕获与原版续接、Runtime 内即时合法性和资源读取、仅故障恢复的看门狗、统一适配器的已验证高层后端、受权限检查的选中/光标/侧栏显示字段更新。它们不等于独立注入；界面操作也并非都要变成网络事件。verification/ARCHITECTURE_AUDIT.json 记录依赖清单、敏感 API 位置、剩余迁移项和生产源码哈希。</p>
<h2>迁移发现并修复的问题</h2><p>合并 DLL 后，原编译单元私有令牌与链接器合并的内联函数可能不一致，导致取得权限却无法调用原版接口；已改为运行库内唯一共享令牌。另补齐共享订阅的独立释放、失效订阅拒绝、唤醒合并与重试、旧线程退出后的迁移、光标停止后重新打开映射、旧运行库并存拒绝。</p>
<h2>验证与实际限制</h2><p>86 项本地检查通过（54 个原生逻辑测试、30 项源码/UI/宿主测试、2 个模拟 Win32 读取测试组）。宿主测试包含两个编译单元共享状态、200 次并发订阅、两个功能共用一组 Hook、独立停止和异常恢复。UI 检查覆盖 155 个控件、12 个视口、1764 次可达性。</p>
<p>实际构建的 GameRuntime.dll 经 x86 仿真执行基础回归、26 项既有专项回归、17 项单运行库回归、15 项源数据时效回归、13 项入口诊断回归及 64 个双端模型场景。结果记录当前 DLL 哈希。新增测试中光标 Hide/Show 的游戏绘制函数是计数桩，运行库的权限、调用与恢复逻辑真实执行。</p>
<p>双端测试使用真实发送端 DLL 与原版事件构造器，传输/接收器为简化模型；帧号推进不等于运行完整游戏 AI、寻路、经济或同步 CRC。没有完成真实 Windows UI/DPI、完整游戏、双机联机或 LBW 验收，不能保证“全功能同时启用绝不延迟”。</p>
<h2>界面预览</h2><p>保留的 0.7.4 布局示意，非 Windows 实机截图；不能作为 0.7.11 绘制修复后的像素验证。</p><img src="UI-Preview.png" alt="战术面板"><img src="UI-Automation-Preview.png" alt="自动化设置">
<h2>功能说明与实现位置（67 项）</h2>'''+features+'''
<h2>源码、构建和测试</h2><p>source/ 是当前完整工程；BUILD_ZIG.cmd / build-zig.sh 使用 Zig 0.13.0 构建 EXE 和唯一 GameRuntime.dll。BUILD_WINDOWS.cmd 是同一构建入口。独立模块构建脚本也转交整套构建。verification/ 包含文件哈希、资源清单、入口检查、回归日志和结构化结果。</p><p>本包保留原版安全路由与对象事件白名单，不因为单 DLL 迁移而额外放开未验证的事件或改变联机规则。内存布局与原版函数地址仍依赖匹配游戏版本；不包含游戏 EXE、编译器或用户个人配置。</p>'''
